void main() {
  vec2 lot = floor(uv * 32.0);
  vec2 shuffle = seed * vec2(7.13, 3.71);
  vec2 block = floor(lot / 4.0) + 3.0 + shuffle;
  float park = step(1.0 - parks, ghee_hash(block));
  float water = step(1.0 - ponds, ghee_hash(block + 19.0));
  gl_FragColor = vec4(park * mix(0.75, 1.0, water), ghee_hash(lot + shuffle), ghee_hash(lot + 7.0 + shuffle), 1.0);
}

float wave(vec2 p, float n) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = mix(ghee_hash(mod(i, n)), ghee_hash(mod(i + vec2(1.0, 0.0), n)), f.x);
  float b = mix(ghee_hash(mod(i + vec2(0.0, 1.0), n)), ghee_hash(mod(i + 1.0, n)), f.x);
  return mix(a, b, f.y);
}

void main() {
  vec2 p = uv * 4.0 + mod(iTime * wind * vec2(1.0, 0.4), 4.0);
  float n = wave(p, 4.0) * 0.65 + wave(p * 2.0 + 5.0, 8.0) * 0.35;
  gl_FragColor = vec4(vec3(smoothstep(0.6, 0.68, n)), 1.0);
}

void main() {
  float t = radians(tilt);
  float a = radians(yaw);
  vec3 forward = vec3(sin(a) * cos(t), cos(a) * cos(t), -sin(t));
  vec3 right = vec3(cos(a), -sin(a), 0.0);
  vec3 up = vec3(sin(a) * sin(t), cos(a) * sin(t), cos(t));
  float view = fov_time > 0.0 ? mix(fov_from, fov, smoothstep(0.0, 1.0, iTime / fov_time)) : fov;
  vec2 lens = vec2(2.0 * iResolution.x / iResolution.y, -2.0) * tan(radians(view) * 0.5);
  vec2 ahead = vec2(sin(a), cos(a));
  vec2 glide = travel.x * right.xy + travel.y * ahead;
  glide *= travel_speed / 32.0 / max(length(travel), 1e-4);
  vec3 eye = vec3(0.5 + pan_x * right.xy + pan_y * ahead + mod(glide * iTime, 1.0), 0.0) - forward / zoom;
  vec2 quad = (floor(gl_FragCoord.xy * 0.5) * 2.0 + 1.0) / iResolution.xy;
  vec3 ray = forward + (quad.x - 0.5) * lens.x * right + (quad.y - 0.5) * lens.y * up;
  float far = 8.0;
  if (ray.z < 0.0) far = min(far, -eye.z / ray.z * zoom);
  vec2 tile = floor(eye.xy + ray.xy * far / zoom);
  ray = forward + (uv.x - 0.5) * lens.x * right + (uv.y - 0.5) * lens.y * up;
  far = 8.0;
  if (ray.z < 0.0) far = min(far, -eye.z / ray.z * zoom);
  vec2 board = eye.xy + ray.xy * far / zoom;
  vec3 col = texture2D(iChannel0, board - tile).rgb;
  gl_FragColor = vec4(mix(col, haze, clamp(0.3 * (far - 1.2), 0.0, 1.0)), clamp(1.5 - 1.0 / far, 0.0, 1.0));
}

void main() {
  vec2 px = spread / iChannelResolution[0].xy;
  vec3 sum = vec3(0.0);
  float total = 0.0;
  for (int x = -2; x <= 2; x++) {
    for (int y = -2; y <= 2; y++) {
      float w = exp(-float(x * x + y * y) / 5.0);
      sum += w * texture2D(iChannel0, uv + vec2(float(x), float(y)) * px).rgb;
      total += w;
    }
  }
  gl_FragColor = vec4(sum / total, 1.0);
}

void main() {
  vec3 col = vec3(0.0);
  if (gl_FragCoord.x >= 0.0) col = texture2D(iChannel0, uv).rgb;
  vec2 q = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  col *= 1.0 - vignette * dot(q, q);
  col += (ghee_hash(floor(uv * iResolution.xy) + fract(iTime) * 97.0) - 0.5) * grain;
  gl_FragColor = vec4(col, 1.0);
}
